import type { VectorLike } from './number';

// Binary dot-like operator
const binary = (f: (a: number, b: number) => number) =>
  <T extends VectorLike>(a: T, b: T): T => {
    const {length} = a;
    const c = a.slice() as T;
    for (let i = 0; i < length; ++i) {
      c[i] = f(a[i], b[i]);
    }
    return c;
  }

// Unary reduction operator
const reduce = (f: (a: number, b: number, i: number) => number) =>
  <T extends VectorLike>(v: T, accum: number = 0): number => {
    const {length} = v;
    for (let i = 0; i < length; ++i) {
      accum = f(accum, v[i], i);
    }
    return accum;
  };

// Binary reduction operator
const reduce2 = (f: (a: number, b: number, c: number, i: number) => number) =>
  <T extends VectorLike>(a: T, b: T, accum: number = 0): number => {
    const {length} = a;
    for (let i = 0; i < length; ++i) {
      accum = f(accum, a[i], b[i], i);
    }
    return accum;
  };

// Scalar operators
const plus     = (x: number, y: number) => x + y;
const minus    = (x: number, y: number) => x - y;
const multiply = (x: number, y: number) => x * y;
const divide   = (x: number, y: number) => x / y;
const minimum  = (x: number, y: number) => Math.min(x, y);
const maximum  = (x: number, y: number) => Math.max(x, y);

const plus2  = (x: number, y: number) => x + y*y;
const mad    = (x: number, y: number, z: number) => x + y*z;
const madl2  = (x: number, y: number, z: number) => x + (y - z) * (y - z);

// Vector operators
const add    = binary(plus);
const sub    = binary(minus);
const mul    = binary(multiply);
const div    = binary(divide);
const dot    = reduce2(mad);
const adds   = <T extends VectorLike>(a: T, s: number) => a.map(x => x + s) as T;
const subs   = <T extends VectorLike>(a: T, s: number) => a.map(x => x - s) as T;
const muls   = <T extends VectorLike>(a: T, s: number) => a.map(x => x * s) as T;
const scale  = muls;

const sum    = reduce(plus);
const len2   = reduce(plus2);
const len    = <T extends VectorLike>(a: T): number => Math.sqrt(len2(a));
const dist2  = reduce2(madl2);
const dist   = <T extends VectorLike>(a: T, b: T): number => Math.sqrt(dist2(a, b));

const abs    = <T extends VectorLike>(a: T): T => a.map(x => Math.abs(x)) as T;
const unit   = <T extends VectorLike>(a: T): T => {
  const l = len(a);
  return scale(a, l ? 1/l : 0);
};

const minEl  = <T extends VectorLike>(a: T)    => reduce(minimum)(a, Infinity);
const maxEl  = <T extends VectorLike>(a: T)    => reduce(maximum)(a, -Infinity);

const min    = <T extends VectorLike>(a: T, b: T): T => a.map((_, i) => Math.min(a[i], b[i])) as T;
const max    = <T extends VectorLike>(a: T, b: T): T => a.map((_, i) => Math.max(a[i], b[i])) as T;
const clamp  = <T extends VectorLike>(vector: T, a: number = 0, b: number = 1): T => vector.map(v => Math.max(a, Math.min(b, v))) as T;

const mins   = <T extends VectorLike>(a: T, b: number): T => a.map((_, i) => Math.min(a[i], b)) as T;
const maxs   = <T extends VectorLike>(a: T, b: number): T => a.map((_, i) => Math.max(a[i], b)) as T;

const lerp    = <T extends VectorLike>(a: T, b: T, t: number): T => add(a, scale(sub(b, a), t));
const project = <T extends VectorLike>(a: T, n: T): T => sub(a, scale(n, dot(a, n)));
const select  = <T extends VectorLike>(a: T, b: T, m: T): T => m.map((s, i) => s ? b[i] : a[i]) as T;

export const Vector = {
  binary,
  reduce,
  reduce2,
  add,
  sub,
  mul,
  div,
  dot,
  adds,
  subs,
  muls,
  mins,
  maxs,
  scale,
  sum,
  len2,
  len,
  dist2,
  dist,
  abs,
  unit,
  minEl,
  maxEl,
  min,
  max,
  clamp,
  lerp,
  project,
  select,
};
